const std = @import("std");
const header = @import("header.zig");
const pointer = @import("pointer.zig");
const security = @import("security.zig");
const tsc = @import("tsc.zig");

const posix = std.posix;
const page_size_min = std.heap.page_size_min;

pub const VfsFaultKind = enum(u8) {
    none,
    torn_write,
    corruption,
    power_off,
};

pub const VfsFaultSpec = struct {
    kind: VfsFaultKind = .none,
    trigger_offset: u64 = 0,
    trigger_size: u64 = 0,
    partial_bytes: u64 = 0,
    flip_bit_offset: u64 = 0,
    armed: bool = false,
};

pub const SimSector = struct {
    data: [512]u8,
    written: bool,
};

pub const SimVfsBackend = struct {
    buf: []align(page_size_min) u8,
    size: u64,
    allocator: std.mem.Allocator,
    fault: VfsFaultSpec,
    sector_written: []bool,
    sector_count: usize,

    pub fn init(allocator: std.mem.Allocator, initial_size: u64) !SimVfsBackend {
        const sz = try alignTo(initial_size, 512);
        if (sz == 0) return error.InvalidHeapSize;

        const buf_len = try u64ToUsize(sz);
        const buf = try allocator.alignedAlloc(u8, page_size_min, buf_len);
        errdefer allocator.free(buf);
        @memset(buf, 0);

        const sector_count = try u64ToUsize(sz / 512);
        const sector_written = try allocator.alloc(bool, sector_count);
        errdefer allocator.free(sector_written);
        @memset(sector_written, false);

        return SimVfsBackend{
            .buf = buf,
            .size = sz,
            .allocator = allocator,
            .fault = .{},
            .sector_written = sector_written,
            .sector_count = sector_count,
        };
    }

    pub fn deinit(self: *SimVfsBackend) void {
        self.allocator.free(self.buf);
        self.allocator.free(self.sector_written);
    }

    pub fn armFault(self: *SimVfsBackend, spec: VfsFaultSpec) void {
        self.fault = spec;
        self.fault.armed = true;
    }

    pub fn disarmFault(self: *SimVfsBackend) void {
        self.fault.armed = false;
        self.fault.kind = .none;
    }

    pub fn writeAt(self: *SimVfsBackend, offset: u64, data: []const u8) !void {
        const data_len = try usizeToU64(data.len);
        try checkRange(self.size, offset, data_len);

        if (self.fault.armed) {
            const fault_start = self.fault.trigger_offset;
            const fault_end = try checkedAddU64(fault_start, self.fault.trigger_size);
            const write_end = try checkedAddU64(offset, data_len);
            const overlaps = offset < fault_end and write_end > fault_start;

            if (overlaps) {
                switch (self.fault.kind) {
                    .torn_write => {
                        const partial = @min(self.fault.partial_bytes, data_len);
                        if (partial > 0) {
                            const start = try u64ToUsize(offset);
                            const end = try u64ToUsize(try checkedAddU64(offset, partial));
                            const partial_usize = try u64ToUsize(partial);
                            @memcpy(self.buf[start..end], data[0..partial_usize]);
                            self.markSectors(offset, partial);
                        }
                        self.fault.armed = false;
                        return error.SimulatedTornWrite;
                    },
                    .corruption => {
                        const start = try u64ToUsize(offset);
                        const end = try u64ToUsize(write_end);
                        @memcpy(self.buf[start..end], data);
                        self.markSectors(offset, data_len);
                        if (self.fault.flip_bit_offset < data_len) {
                            const byte_idx = try u64ToUsize(try checkedAddU64(offset, self.fault.flip_bit_offset));
                            self.buf[byte_idx] ^= 0xFF;
                        }
                        self.fault.armed = false;
                        return;
                    },
                    .power_off => {
                        self.fault.armed = false;
                        return error.SimulatedPowerOff;
                    },
                    .none => {},
                }
            }
        }

        const start = try u64ToUsize(offset);
        const end = try u64ToUsize(try checkedAddU64(offset, data_len));
        @memcpy(self.buf[start..end], data);
        self.markSectors(offset, data_len);
    }

    pub fn readAt(self: *const SimVfsBackend, offset: u64, buf: []u8) !void {
        const len = try usizeToU64(buf.len);
        try checkRange(self.size, offset, len);
        const start = try u64ToUsize(offset);
        const end = try u64ToUsize(try checkedAddU64(offset, len));
        @memcpy(buf, self.buf[start..end]);
    }

    pub fn syncRange(self: *SimVfsBackend, offset: u64, len: u64) !void {
        try checkRange(self.size, offset, len);
    }

    pub fn fsync(self: *SimVfsBackend) !void {
        _ = self;
    }

    pub fn grow(self: *SimVfsBackend, new_size: u64) !void {
        if (new_size <= self.size) return;

        const aligned = try alignTo(new_size, 512);
        const old_size = self.size;
        const old_len = try u64ToUsize(old_size);
        const new_len = try u64ToUsize(aligned);

        const new_buf = try self.allocator.alignedAlloc(u8, page_size_min, new_len);
        errdefer self.allocator.free(new_buf);
        @memcpy(new_buf[0..old_len], self.buf[0..old_len]);
        @memset(new_buf[old_len..new_len], 0);

        const new_sector_count = try u64ToUsize(aligned / 512);
        const new_sectors = try self.allocator.alloc(bool, new_sector_count);
        errdefer self.allocator.free(new_sectors);
        @memcpy(new_sectors[0..self.sector_count], self.sector_written[0..self.sector_count]);
        @memset(new_sectors[self.sector_count..new_sector_count], false);

        self.allocator.free(self.buf);
        self.allocator.free(self.sector_written);

        self.buf = new_buf;
        self.size = aligned;
        self.sector_written = new_sectors;
        self.sector_count = new_sector_count;
    }

    fn markSectors(self: *SimVfsBackend, offset: u64, len: u64) void {
        if (len == 0 or offset >= self.size) return;

        const capped_len = @min(len, self.size - offset);
        if (capped_len == 0) return;

        const start_sector = offset / 512;
        const end_offset = offset + capped_len;
        const end_sector = (end_offset + 511) / 512;

        var s = start_sector;
        while (s < end_sector and s < @as(u64, @intCast(self.sector_count))) : (s += 1) {
            self.sector_written[@intCast(s)] = true;
        }
    }
};

pub const VfsKind = enum { prod, sim };

pub const VfsHandle = struct {
    kind: VfsKind,
    prod_base: []align(page_size_min) u8,
    prod_size: u64,
    prod_file: std.fs.File,
    sim: ?*SimVfsBackend,

    pub fn writeRange(self: *VfsHandle, offset: u64, data: []const u8) !void {
        const len = try usizeToU64(data.len);
        try checkRange(self.currentSize(), offset, len);

        switch (self.kind) {
            .prod => {
                const idx = try u64ToUsize(offset);
                @memcpy(self.prod_base[idx..][0..data.len], data);
            },
            .sim => {
                try self.sim.?.writeAt(offset, data);
            },
        }
    }

    pub fn readRange(self: *const VfsHandle, offset: u64, buf: []u8) !void {
        const len = try usizeToU64(buf.len);
        try checkRange(self.currentSize(), offset, len);

        switch (self.kind) {
            .prod => {
                const idx = try u64ToUsize(offset);
                @memcpy(buf, self.prod_base[idx..][0..buf.len]);
            },
            .sim => {
                try self.sim.?.readAt(offset, buf);
            },
        }
    }

    pub fn syncRange(self: *VfsHandle, offset: u64, len: u64) !void {
        try checkRange(self.currentSize(), offset, len);

        switch (self.kind) {
            .prod => try flushRangeRaw(self.prod_base, offset, len),
            .sim => try self.sim.?.syncRange(offset, len),
        }
    }

    pub fn fsync(self: *VfsHandle) !void {
        switch (self.kind) {
            .prod => try posix.fsync(self.prod_file.handle),
            .sim => try self.sim.?.fsync(),
        }
    }

    pub fn basePtr(self: *const VfsHandle) [*]u8 {
        switch (self.kind) {
            .prod => return self.prod_base.ptr,
            .sim => return self.sim.?.buf.ptr,
        }
    }

    pub fn currentSize(self: *const VfsHandle) u64 {
        switch (self.kind) {
            .prod => return self.prod_size,
            .sim => return self.sim.?.size,
        }
    }

    pub fn grow(self: *VfsHandle, new_size: u64) !void {
        if (new_size <= self.currentSize()) return;

        switch (self.kind) {
            .prod => {
                try posix.msync(self.prod_base, posix.MSF.SYNC);
                try self.prod_file.setEndPos(new_size);

                const new_len = try u64ToUsize(new_size);
                const new_map = try posix.mmap(
                    null,
                    new_len,
                    posix.PROT.READ | posix.PROT.WRITE,
                    .{ .TYPE = .SHARED },
                    self.prod_file.handle,
                    0,
                );

                posix.munmap(self.prod_base);
                self.prod_base = new_map;
                self.prod_size = new_size;
            },
            .sim => try self.sim.?.grow(new_size),
        }
    }
};

const ReadObjectResult = struct {
    header: header.ObjectHeader,
    data: []const u8,
};

const OpenResult = struct {
    file: std.fs.File,
    needs_init: bool,
    map_size: u64,
};

const PreviousFreeBlock = struct {
    hdr_offset: u64,
    data_offset: u64,
    size: u64,
};

pub const PersistentHeap = struct {
    vfs: VfsHandle,
    size: u64,
    mapped_size: u64,
    file_path: []u8,
    heap_header: *header.HeapHeader,
    pool_uuid: u128,
    security: ?*security.SecurityManager,
    allocator: std.mem.Allocator,
    dirty_pages: []bool,
    dirty_page_count: u64,
    is_dirty: bool,

    const MMAP_PROT: u32 = posix.PROT.READ | posix.PROT.WRITE;
    const MMAP_FLAGS: posix.MAP = .{ .TYPE = .SHARED };

    pub fn init(
        allocator: std.mem.Allocator,
        file_path: []const u8,
        size: u64,
        security_mgr: ?*security.SecurityManager,
    ) !*PersistentHeap {
        const self = try allocator.create(PersistentHeap);
        errdefer allocator.destroy(self);

        const path_copy = try allocator.dupe(u8, file_path);
        errdefer allocator.free(path_copy);

        const requested_size = try normalizeHeapSize(@max(size, minimumHeapSize()));

        if (tsc.is_simulation) {
            const sim_backend = try allocator.create(SimVfsBackend);
            errdefer allocator.destroy(sim_backend);
            sim_backend.* = try SimVfsBackend.init(allocator, requested_size);
            errdefer sim_backend.deinit();

            const page_count = try pageCountForSize(requested_size);
            const dirty_pages = try allocator.alloc(bool, page_count);
            errdefer allocator.free(dirty_pages);
            @memset(dirty_pages, false);

            const heap_hdr: *header.HeapHeader = @ptrCast(@alignCast(sim_backend.buf.ptr));
            @memset(sim_backend.buf[0..try u64ToUsize(requested_size)], 0);
            heap_hdr.* = header.HeapHeader.init(requested_size);
            heap_hdr.used_size = allocationStartOffset();
            heap_hdr.setDirty(false);
            heap_hdr.updateChecksum();

            const vfs = VfsHandle{
                .kind = .sim,
                .prod_base = undefined,
                .prod_size = 0,
                .prod_file = undefined,
                .sim = sim_backend,
            };

            self.* = PersistentHeap{
                .vfs = vfs,
                .size = requested_size,
                .mapped_size = requested_size,
                .file_path = path_copy,
                .heap_header = heap_hdr,
                .pool_uuid = heap_hdr.getPoolUUID(),
                .security = security_mgr,
                .allocator = allocator,
                .dirty_pages = dirty_pages,
                .dirty_page_count = 0,
                .is_dirty = false,
            };

            if (self.pool_uuid == 0) return error.InvalidPoolUUID;
            try self.vfs.syncRange(0, requested_size);
            return self;
        }

        const open_result = try openOrCreateFile(file_path, requested_size);
        var file = open_result.file;
        errdefer file.close();

        const mapped_size = open_result.map_size;
        if (mapped_size < minimumHeapSize()) return error.InvalidHeapSize;

        const base_addr = try mapFile(file.handle, mapped_size);
        errdefer unmapFile(base_addr);

        const heap_hdr: *header.HeapHeader = @ptrCast(@alignCast(base_addr.ptr));
        var heap_size: u64 = mapped_size;

        if (open_result.needs_init) {
            @memset(base_addr[0..try u64ToUsize(mapped_size)], 0);
            heap_hdr.* = header.HeapHeader.init(mapped_size);
            heap_hdr.used_size = allocationStartOffset();
            heap_hdr.setDirty(false);
            heap_hdr.updateChecksum();
            try flushRangeRaw(base_addr, 0, heapHeaderSize());
            heap_size = mapped_size;
        } else {
            try heap_hdr.validate();
            heap_size = heap_hdr.heap_size;

            if (heap_size < minimumHeapSize()) return error.InvalidHeapSize;
            if (heap_size > mapped_size) return error.InvalidHeapSize;
            if (heap_size % pageSize() != 0) return error.InvalidHeapSize;
            if (heap_hdr.used_size < allocationStartOffset()) return error.InvalidHeapHeader;
            if (heap_hdr.used_size > heap_size) return error.InvalidHeapHeader;
        }

        const pool_uuid = heap_hdr.getPoolUUID();
        if (pool_uuid == 0) return error.InvalidPoolUUID;

        const page_count = try pageCountForSize(mapped_size);
        const dirty_pages = try allocator.alloc(bool, page_count);
        errdefer allocator.free(dirty_pages);
        @memset(dirty_pages, false);

        const vfs = VfsHandle{
            .kind = .prod,
            .prod_base = base_addr,
            .prod_size = mapped_size,
            .prod_file = file,
            .sim = null,
        };

        self.* = PersistentHeap{
            .vfs = vfs,
            .size = heap_size,
            .mapped_size = mapped_size,
            .file_path = path_copy,
            .heap_header = heap_hdr,
            .pool_uuid = pool_uuid,
            .security = security_mgr,
            .allocator = allocator,
            .dirty_pages = dirty_pages,
            .dirty_page_count = 0,
            .is_dirty = false,
        };

        return self;
    }

    pub fn deinit(self: *PersistentHeap) !void {
        const alloc = self.allocator;
        defer {
            switch (self.vfs.kind) {
                .prod => {
                    unmapFile(self.vfs.prod_base);
                    self.vfs.prod_file.close();
                },
                .sim => {
                    if (self.vfs.sim) |sim| {
                        sim.deinit();
                        alloc.destroy(sim);
                    }
                },
            }
            alloc.free(self.dirty_pages);
            alloc.free(self.file_path);
            alloc.destroy(self);
        }

        try self.sync();
    }

    pub fn getSimBackend(self: *PersistentHeap) ?*SimVfsBackend {
        if (self.vfs.kind == .sim) return self.vfs.sim;
        return null;
    }

    pub fn getSize(self: *const PersistentHeap) u64 {
        return self.size;
    }

    pub fn getUsedSize(self: *const PersistentHeap) u64 {
        return self.heap_header.used_size;
    }

    pub fn getBaseAddress(self: *PersistentHeap) [*]u8 {
        return self.vfs.basePtr();
    }

    pub fn getPoolUUID(self: *const PersistentHeap) u128 {
        return self.pool_uuid;
    }

    pub fn getRoot(self: *const PersistentHeap) ?pointer.PersistentPtr {
        const root = self.heap_header.getRootPtr();
        if (root) |r| {
            if (r.uuid != self.pool_uuid) return null;
            if (r.offset >= self.size) return null;
            return pointer.PersistentPtr{
                .pool_uuid = r.uuid,
                .offset = r.offset,
            };
        }
        return null;
    }

    pub fn setRoot(self: *PersistentHeap, tx: anytype, ptr: pointer.PersistentPtr) !void {
        _ = tx;

        if (!ptr.isNull()) {
            if (ptr.pool_uuid != self.pool_uuid) return error.UUIDMismatch;
            if (ptr.offset >= self.size) return error.OutOfBounds;
        }

        self.heap_header.setRootPtr(ptr.offset, ptr.pool_uuid);
        try self.persistHeapHeader();
    }

    pub fn resolvePtr(self: *const PersistentHeap, ptr: pointer.PersistentPtr) !?*anyopaque {
        if (ptr.isNull()) return null;
        if (ptr.pool_uuid != self.pool_uuid) return error.UUIDMismatch;
        if (ptr.offset >= self.size) return error.OutOfBounds;

        const base = self.vfs.basePtr();
        const idx = try u64ToUsize(ptr.offset);
        return @ptrCast(base + idx);
    }

    pub fn getNativePtr(
        self: *const PersistentHeap,
        comptime T: type,
        ptr: pointer.PersistentPtr,
    ) !?*T {
        if (ptr.isNull()) return null;

        if (@alignOf(T) > 1) {
            const required_alignment: u64 = @intCast(@alignOf(T));
            if (ptr.offset % required_alignment != 0) return error.InvalidAlignment;
        }

        const hdr_offset = try self.findObjectHeaderOffset(ptr.offset);
        const obj_header = try self.readObjectHeaderAt(hdr_offset);
        if (obj_header.isFreed()) return null;

        const type_size: u64 = @intCast(@sizeOf(T));
        if (type_size > @as(u64, @intCast(obj_header.size))) return error.SizeMismatch;

        const raw = try self.resolvePtr(ptr);
        if (raw) |r| return @ptrCast(@alignCast(r));
        return null;
    }

    pub fn allocate(
        self: *PersistentHeap,
        tx: anytype,
        size: u64,
        alignment: u64,
    ) !pointer.PersistentPtr {
        _ = tx;

        if (size == 0) return error.InvalidSize;
        if (!isPowerOfTwo(alignment)) return error.InvalidAlignment;

        const actual_alignment = @max(alignment, minimumPayloadAlignment());
        const want = @max(size, minimumPayloadSize());

        if (smallClassSizeFor(want)) |class_size| {
            if (try self.takeSmallFreeBlock(class_size, actual_alignment)) |ptr| return ptr;
            if (try self.takeLargeFreeBlock(class_size, actual_alignment)) |ptr| return ptr;
            return self.bumpBlock(class_size, actual_alignment);
        }

        if (try self.takeLargeFreeBlock(want, actual_alignment)) |ptr| return ptr;

        return self.bumpBlock(want, actual_alignment);
    }

    fn takeSmallFreeBlock(self: *PersistentHeap, class_size: u64, alignment: u64) !?pointer.PersistentPtr {
        const class_idx = exactSmallClassIndex(class_size) orelse return null;
        const storage = self.freeListStorage();
        var cur = storage[class_idx];
        var steps: u64 = 0;
        const max_steps = self.size / @max(minimumPayloadSize(), @as(u64, 1)) + 1;

        while (cur != 0 and steps < max_steps) : (steps += 1) {
            try checkRange(self.size, cur, @sizeOf(header.FreeListNode));
            const node = header.freeListNodeAt(self.vfs.basePtr(), cur);
            const next = node.next;

            if (cur % alignment == 0) {
                const hdr_offset = try headerOffsetFromDataOffset(cur);
                const obj_header = try self.readObjectHeaderAt(hdr_offset);
                const block_size: u64 = @intCast(obj_header.size);

                if (obj_header.isFreed() and block_size >= class_size) {
                    header.freeListUnlink(self.vfs.basePtr(), &storage[class_idx], cur);
                    try self.markDirty(0, freeListRegionEnd());
                    try self.markDirty(cur, @sizeOf(header.FreeListNode));
                    try self.writeObjectHeaderAt(hdr_offset, block_size);
                    try self.flushRangeAt(0, freeListRegionEnd());
                    try self.flushRangeAt(cur, @sizeOf(header.FreeListNode));
                    try self.flushRangeAt(hdr_offset, objectHeaderSize());

                    return pointer.PersistentPtr{
                        .pool_uuid = self.pool_uuid,
                        .offset = cur,
                    };
                }
            }

            cur = next;
        }

        return null;
    }

    fn takeLargeFreeBlock(self: *PersistentHeap, want: u64, alignment: u64) !?pointer.PersistentPtr {
        var cur = self.heap_header.allocator_offset;
        var steps: u64 = 0;
        const max_steps = self.size / @max(minimumPayloadSize(), @as(u64, 1)) + 1;

        while (cur != 0 and steps < max_steps) : (steps += 1) {
            try checkRange(self.size, cur, @sizeOf(header.FreeListNode));

            const node = header.freeListNodeAt(self.vfs.basePtr(), cur);
            const next = node.next;

            const hdr_offset = try headerOffsetFromDataOffset(cur);
            const obj_header = try self.readObjectHeaderAt(hdr_offset);
            const block_size: u64 = @intCast(obj_header.size);

            if (obj_header.isFreed()) {
                if (try self.carveLargeFreeBlock(cur, block_size, want, alignment)) |ptr| return ptr;
            }

            cur = next;
        }

        return null;
    }

    fn carveLargeFreeBlock(
        self: *PersistentHeap,
        free_data_offset: u64,
        free_size: u64,
        want: u64,
        alignment: u64,
    ) !?pointer.PersistentPtr {
        const oh_size = objectHeaderSize();
        const block_end = try checkedAddU64(free_data_offset, free_size);
        if (block_end > self.size) return error.OutOfBounds;

        var data_offset = try alignTo(free_data_offset, alignment);

        while (data_offset <= block_end) {
            var prefix_size: u64 = 0;
            if (data_offset != free_data_offset) {
                if (data_offset < free_data_offset) return error.IntegerOverflow;
                if (data_offset < try checkedAddU64(free_data_offset, oh_size)) {
                    data_offset = try checkedAddU64(data_offset, alignment);
                    continue;
                }

                prefix_size = data_offset - oh_size - free_data_offset;
                if (prefix_size < minimumPayloadSize()) {
                    data_offset = try checkedAddU64(data_offset, alignment);
                    continue;
                }
            }

            const requested_end = try checkedAddU64(data_offset, want);
            if (requested_end > block_end) return null;

            const suffix_total = block_end - requested_end;
            const split_suffix = suffix_total >= try checkedAddU64(oh_size, minimumPayloadSize());
            const alloc_size = if (split_suffix) want else block_end - data_offset;
            const alloc_hdr_offset = try headerOffsetFromDataOffset(data_offset);

            header.freeListUnlink(self.vfs.basePtr(), &self.heap_header.allocator_offset, free_data_offset);
            try self.markDirty(0, freeListRegionEnd());
            try self.markDirty(free_data_offset, @sizeOf(header.FreeListNode));

            if (prefix_size > 0) {
                const prefix_hdr_offset = try headerOffsetFromDataOffset(free_data_offset);
                try self.writeFreedObjectHeaderAt(prefix_hdr_offset, prefix_size);
                try self.freeListInsert(free_data_offset, prefix_size);
            }

            try self.writeObjectHeaderAt(alloc_hdr_offset, alloc_size);

            if (split_suffix) {
                const suffix_hdr_offset = requested_end;
                const suffix_data_offset = try checkedAddU64(suffix_hdr_offset, oh_size);
                const suffix_size = block_end - suffix_data_offset;
                try self.writeFreedObjectHeaderAt(suffix_hdr_offset, suffix_size);
                try self.freeListInsert(suffix_data_offset, suffix_size);
            }

            try self.flushRangeAt(0, freeListRegionEnd());
            try self.flushRangeAt(free_data_offset, @sizeOf(header.FreeListNode));
            if (prefix_size > 0) {
                try self.flushRangeAt(try headerOffsetFromDataOffset(free_data_offset), objectHeaderSize());
            }
            try self.flushRangeAt(alloc_hdr_offset, objectHeaderSize());
            if (split_suffix) {
                try self.flushRangeAt(requested_end, objectHeaderSize());
                try self.flushRangeAt(try checkedAddU64(requested_end, oh_size), @sizeOf(header.FreeListNode));
            }

            return pointer.PersistentPtr{
                .pool_uuid = self.pool_uuid,
                .offset = data_offset,
            };
        }

        return null;
    }

    fn bumpBlock(self: *PersistentHeap, block_size: u64, alignment: u64) !pointer.PersistentPtr {
        const current_used = @max(self.heap_header.used_size, allocationStartOffset());
        const data_preferred = try checkedAddU64(current_used, objectHeaderSize());
        const data_offset = try alignTo(data_preferred, alignment);
